import json
from fastmcp import Server

server = Server("config-server")

@server.resource("data://config")
def read_config():
    """Read and return the configuration dictionary."""
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "debug": True,
        "database": {
            "host": "localhost",
            "port": 5432,
            "name": "mydb"
        },
        "api": {
            "host": "0.0.0.0",
            "port": 8000
        },
        "features": {
            "caching": True,
            "logging": True
        }
    }
    return json.dumps(config, indent=2)

if __name__ == "__main__":
    server.run()
